<script setup>
import { ref, onMounted } from 'vue'
import { api } from '../../api/client'
const catalog = ref([]), selected = ref('menu_item'), rows = ref([]), schema = ref(null), body = ref(null), editing = ref(null), error = ref(''), busy = ref(false), after = ref('')
const protectedTables = new Set(['invoice','invoice_line','invoice_line_ingredient','payment','ticket','pager_device','shift','cash_entry','stock_lot','stock_movement','point_ledger','fulfillment_event','audit_log','approval_request','async_operation','dining_session'])
const managed = new Set(['id','created_at','updated_at','password_hash','pin_hash','failed_count','locked_until','refresh_version','paid_total','handed_qty','qty_remaining','reserved_qty','points_balance','balance_after','actor_id','created_by','staff_id','requested_by','issued_by','opened_by','approved_by','approver_id','paid_amount','qty_received','qty_rejected','used_count'])
const endpoint = () => '/api/v1/' + selected.value.replaceAll('_','-')
async function load(append = false) { busy.value = true; error.value = ''; try { if (!append) { rows.value = []; after.value = ''; schema.value = await api(endpoint() + '/schema') } const data = await api(endpoint() + '?size=50' + (append && after.value ? '&after=' + after.value : '')); rows.value.push(...data); after.value = data.length === 50 ? data.at(-1).id : '' } catch (e) { error.value = e.message } finally { busy.value = false } }
onMounted(async () => { try { catalog.value = await api('/api/v1/database/catalog'); await load() } catch (e) { error.value = e.message } })
function edit(row) { editing.value = row; body.value = {}; for (const c of schema.value.columns) if (!managed.has(c.name)) body.value[c.name] = row ? (['jsonb','_uuid'].includes(c.type) ? JSON.stringify(row[c.name]) : row[c.name]) : '' }
async function save() { busy.value = true; error.value = ''; try { const payload = {}; for (const c of schema.value.columns) { if (managed.has(c.name)) continue; const value = body.value[c.name]; if (!editing.value && (value === '' || value === null || value === undefined)) continue; if (editing.value && c.name === 'status' && value === editing.value[c.name]) continue; payload[c.name] = value === '' && c.nullable ? null : ['jsonb','_uuid'].includes(c.type) && value !== null ? JSON.parse(value) : c.type === 'bool' ? value === true || value === 'true' : value } await api(endpoint() + (editing.value ? '/' + editing.value.id : ''), { method: editing.value ? 'PATCH' : 'POST', headers: editing.value ? { 'X-Expected-Updated-At': editing.value.updated_at || editing.value.created_at } : {}, body: payload }); body.value = null; await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function remove(row) { if (!window.confirm('Ngừng hoặc xóa bản ghi danh mục này?')) return; try { await api(endpoint() + '/' + row.id, { method: 'DELETE', headers: { 'X-Expected-Updated-At': row.updated_at || row.created_at } }); await load() } catch (e) { error.value = e.message } }
function compact(row) { return JSON.stringify(row, null, 2) }
</script>
<template><h1>Danh mục quản trị từ database</h1><p>Dữ liệu vận hành và sổ tiền/kho chỉ đọc tại đây. Chuyển sang màn hình Đơn hoặc Ca để thực hiện nghiệp vụ.</p><label>Danh mục<select v-model="selected" @change="body = null; load()"><option v-for="t in catalog" :key="t.name" :value="t.name">{{ t.name }}</option></select></label><p v-if="error" class="error">{{ error }}</p><div class="actions"><button :disabled="busy" @click="load()">Tải lại</button><button v-if="!protectedTables.has(selected) && !['app_user','user_access'].includes(selected)" :disabled="busy" @click="edit(null)">Thêm danh mục</button></div><form v-if="body" class="card" @submit.prevent="save"><label v-for="c in schema.columns.filter(c => !managed.has(c.name))" :key="c.name">{{ c.name }}<textarea v-if="c.type === 'jsonb' || c.type === '_uuid'" v-model="body[c.name]" rows="3"></textarea><select v-else-if="c.type === 'bool'" v-model="body[c.name]"><option :value="true">Có</option><option :value="false">Không</option></select><input v-else v-model="body[c.name]" :maxlength="c.maxLength || 10000"></label><div class="actions"><button :disabled="busy">Lưu thật lên server</button><button type="button" class="secondary" @click="body = null">Hủy</button></div></form><article v-for="row in rows" :key="row.id" class="card"><strong>{{ row.name || row.full_name || row.invoice_no || row.code || row.id }}</strong><details><summary>Chi tiết dữ liệu</summary><pre>{{ compact(row) }}</pre></details><div v-if="!protectedTables.has(selected) && !['app_user','user_access'].includes(selected)" class="actions"><button class="secondary" @click="edit(row)">Sửa</button><button class="danger" @click="remove(row)">Ngừng hoặc xóa</button></div></article><button v-if="after" :disabled="busy" @click="load(true)">Tải thêm 50 bản ghi</button></template>
